export async function getAccessTokenForApi() {
  const supabase = await createClient()
  const {
    data: { session },
  } = await supabase.auth.getSession()

  // getSession() is used here only because Phase 18 needs the raw token
  // to forward to NestJS. NestJS must verify the token before trusting it.
  return session?.access_token ?? null
}

